import{_ as t,o as n,c as o,a2 as i}from"./chunks/framework.mrTIYZc5.js";const g=JSON.parse('{"title":"When Not to Use DSO","description":"","frontmatter":{},"headers":[],"relativePath":"guide/when-not-to-use.md","filePath":"guide/when-not-to-use.md"}'),r={name:"guide/when-not-to-use.md"};function s(a,e,l,c,d,h){return n(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="when-not-to-use-dso" tabindex="-1">When Not to Use DSO <a class="header-anchor" href="#when-not-to-use-dso" aria-label="Permalink to &quot;When Not to Use DSO&quot;">​</a></h1><p>While DSO is highly versatile, it is designed for a specific set of use cases. This page outlines the technical constraints and environments where DSO may not be the optimal solution.</p><hr><h2 id="_1-kubernetes-native-environments" tabindex="-1">1. Kubernetes-Native Environments <a class="header-anchor" href="#_1-kubernetes-native-environments" aria-label="Permalink to &quot;1. Kubernetes-Native Environments&quot;">​</a></h2><p>If your workload is already running on Kubernetes (EKS, GKE, AKS, or bare-metal K8s), <strong>use the official External Secrets Operator (ESO)</strong>.</p><ul><li><strong>Why</strong>: ESO is the industry standard for Kubernetes, with native CRD support and deep integration with the K8s RBAC system. DSO is built specifically for teams who are <em>not</em> on Kubernetes.</li></ul><h2 id="_2-windows-based-docker-hosts" tabindex="-1">2. Windows-Based Docker Hosts <a class="header-anchor" href="#_2-windows-based-docker-hosts" aria-label="Permalink to &quot;2. Windows-Based Docker Hosts&quot;">​</a></h2><p>DSO relies on Linux-specific kernel features (Unix sockets, <code>tmpfs</code>, and specific Docker Engine APIs) for its security and injection model.</p><ul><li><strong>Constraint</strong>: DSO is currently <strong>Linux-only</strong>. It does not support Docker Desktop on Windows (WSL2) or native Windows containers.</li></ul><h2 id="_3-high-churn-serverless-functions-aws-lambda-etc" tabindex="-1">3. High-Churn Serverless Functions (AWS Lambda, etc.) <a class="header-anchor" href="#_3-high-churn-serverless-functions-aws-lambda-etc" aria-label="Permalink to &quot;3. High-Churn Serverless Functions (AWS Lambda, etc.)&quot;">​</a></h2><p>DSO&#39;s agent architecture is designed for long-running Docker Engine instances.</p><ul><li><strong>Why</strong>: Serverless environments like AWS Lambda or Google Cloud Run have their own native secret injection mechanisms. The overhead of the DSO agent is unnecessary for short-lived, transient functions.</li></ul><h2 id="_4-legacy-docker-engine-v20-10" tabindex="-1">4. Legacy Docker Engine (&lt; v20.10) <a class="header-anchor" href="#_4-legacy-docker-engine-v20-10" aria-label="Permalink to &quot;4. Legacy Docker Engine (&lt; v20.10)&quot;">​</a></h2><p>DSO leverages modern Docker Engine features for its &quot;Zero-Persistence&quot; injection and lifecycle monitoring.</p><ul><li><strong>Constraint</strong>: While DSO may work on older versions, it is only officially supported and tested on <strong>Docker Engine v20.10 and later</strong>.</li></ul><h2 id="_5-non-docker-workloads" tabindex="-1">5. Non-Docker Workloads <a class="header-anchor" href="#_5-non-docker-workloads" aria-label="Permalink to &quot;5. Non-Docker Workloads&quot;">​</a></h2><p>DSO is deeply coupled with the Docker Engine and its metadata (Labels).</p><ul><li><strong>Why</strong>: If you need to manage secrets for non-containerized Linux processes (e.g., standard systemd services), consider using a direct integration with HashiCorp Vault or a cloud-specific secret manager CLI.</li></ul><hr><h2 id="technical-limitations" tabindex="-1">Technical Limitations <a class="header-anchor" href="#technical-limitations" aria-label="Permalink to &quot;Technical Limitations&quot;">​</a></h2><ul><li><strong>Binary-Only Providers</strong>: DSO uses an RPC-based plugin model. Adding a custom provider requires writing a Go binary that implements the DSO Provider interface.</li><li><strong>No Native HSM Integration</strong>: DSO provides a high-security software layer but does not currently offer direct integration with hardware security modules (HSMs).</li></ul><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><strong><a href="/docs/guide/design-principles.html">Design Principles</a></strong>: The core pillars of the project.</li><li><strong><a href="/docs/guide/architecture.html">System Architecture</a></strong>: Deep dive into the internal engines.</li><li><strong><a href="/docs/guide/security.html">Security Model</a></strong>: Detailed threat mitigations.</li></ul>',23)])])}const m=t(r,[["render",s]]);export{g as __pageData,m as default};
